import{_ as t,o as a,c as s,a0 as o}from"./chunks/framework.CNXp-E7Q.js";const p=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),n={name:"explanation/decisions.md"};function r(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the calls that shaped bupha, the alternatives rejected, and the consequences we live with. The repo&#39;s <code>adrs/</code> hold the full versions — this page is the map.</p><h2 id="bupha-is-ci-semantics-not-a-product" tabindex="-1">bupha is CI semantics, not a product <a class="header-anchor" href="#bupha-is-ci-semantics-not-a-product" aria-label="Permalink to &quot;bupha is CI semantics, not a product&quot;">​</a></h2><p><strong>Decision:</strong> bupha owns queue semantics, runner dialects, forge status write-back — and <em>nothing</em> else. Substrate is hypha/peregrin, distribution is tamias, secrets are cuora (ADR-0006, resolved by the crate-scope audit).</p><p><strong>Alternatives:</strong> a standalone CI server (UI, YAML DSL, managed fleet); keeping queue/service/tunnel machinery in-repo.</p><p><strong>Consequence:</strong> every concern bupha <em>doesn&#39;t</em> own already has a home — the audit retired <code>bupha-{secret,keyring,dotenv,service, systemd,tunnel,cloudflared}</code> and folded webhook/tunnel into <code>bupha-watch</code> for standalone mode only. The price: bupha depends on the org stack (hypha plane, tamias packs, cuora secrets) to be useful at fleet scale — single-box dev mode stays self-contained.</p><h2 id="fleets-ship-as-tamias-bundles" tabindex="-1">Fleets ship as tamias bundles <a class="header-anchor" href="#fleets-ship-as-tamias-bundles" aria-label="Permalink to &quot;Fleets ship as tamias bundles&quot;">​</a></h2><p><strong>Decision:</strong> a CI fleet is a <code>type: bupha</code> content pack — <code>tamias install</code>/<code>deploy</code> provisions units, config, and forge hooks; <code>tamias-driver-bupha host</code>/<code>worker</code> runs the engine in-process.</p><p><strong>Alternatives:</strong> a <code>bupha install</code>/<code>service</code> lifecycle of its own; a daemon bupha owns.</p><p><strong>Consequence:</strong> install/update/teardown is tamias&#39;s problem and the <code>bupha</code> command shrank to a dev harness (no <code>[[bin]]</code> — the pack shim carries it). The cost: the product path requires tamias + systemd; bare-metal single-box use is the dev CLI&#39;s job.</p><h2 id="push-→-status-with-honest-verdicts" tabindex="-1">Push → status with honest verdicts <a class="header-anchor" href="#push-→-status-with-honest-verdicts" aria-label="Permalink to &quot;Push → status with honest verdicts&quot;">​</a></h2><p><strong>Decision:</strong> HMAC-verified webhooks feed a per-job queue with two policies — <code>latest</code> (latest-wins, <code>cancel_running</code>) for gates, <code>all</code> (bounded FIFO) for releases — and every terminal state posts a commit status, including honest &quot;cancelled&quot;/&quot;error&quot; for superseded shas.</p><p><strong>Alternatives:</strong> fire-and-forget runs with no status; always-run- everything queues.</p><p><strong>Consequence:</strong> instant feedback on self-owned hardware with a truthful status surface — a superseded sha never silently drops. The cost: one global worker serializes runs (deliberate, documented) and <code>all</code>-mode promises cap at 32 pending.</p><h2 id="gha-is-a-dialect-not-parity" tabindex="-1"><code>gha</code> is a dialect, not parity <a class="header-anchor" href="#gha-is-a-dialect-not-parity" aria-label="Permalink to &quot;`gha` is a dialect, not parity&quot;">​</a></h2><p><strong>Decision:</strong> <code>runner.kind = &quot;gha&quot;</code> executes a documented subset of <code>.github/workflows</code> YAML natively; everything outside hard-errors at spawn naming the key.</p><p><strong>Alternatives:</strong> embedding act/runner; a YAML DSL of bupha&#39;s own; silent best-effort skipping.</p><p><strong>Consequence:</strong> real workflows migrate incrementally — the dogfood report (<a href="./gha-dogfood.html">gha-dogfood</a>) enumerates exactly what works. The honest-failure contract means a workflow either runs correctly or fails loudly at spawn; it never half-runs. GHA remains the answer for matrices, marketplace actions, and multi-OS fleets (<a href="./../comparison.html">comparison</a>).</p><h2 id="the-ci-job-entity-plane-is-the-durable-queue" tabindex="-1">The ci-job entity plane is the durable queue <a class="header-anchor" href="#the-ci-job-entity-plane-is-the-durable-queue" aria-label="Permalink to &quot;The ci-job entity plane is the durable queue&quot;">​</a></h2><p><strong>Decision:</strong> fleet-scale queue state lives as <code>ci-job</code> entities on the hypha/peregrin node; workers claim with fence+lease CAS. The in-repo queue impls (<code>redb</code>/<code>redis</code>) were retired — dev mode keeps the <code>json</code> store.</p><p><strong>Alternatives:</strong> keeping embedded redb/redis queue impls; building a bupha-owned distributed queue.</p><p><strong>Consequence:</strong> one queue implementation org-wide with replay dedup for free (deterministic entity ids) — but the fleet path requires a hypha/peregrin node, and label routing (<code>runs_on</code>) is the only scheduling dimension.</p><h2 id="secrets-resolve-env-→-cuora-→-env-file" tabindex="-1">Secrets resolve env → cuora → env-file <a class="header-anchor" href="#secrets-resolve-env-→-cuora-→-env-file" aria-label="Permalink to &quot;Secrets resolve env → cuora → env-file&quot;">​</a></h2><p><strong>Decision:</strong> config names secrets (<code>secret_env</code>/<code>token_env</code>); values resolve through env → <code>cuora://bupha/&lt;NAME&gt;</code> → <code>~/.config/bupha/env</code>, with the token reaching runners via <code>env://</code>-style indirection — never argv, never config.</p><p><strong>Alternatives:</strong> values in config; the OS keyring as canonical (dropped post-T-077).</p><p><strong>Consequence:</strong> the canonical path is cuora with an honest dev fallback; keyring entries survive only as hypha-backed legacy reads.</p>',26)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
